const float PI = atan(0.0, -1.0);
const vec2 UNIT = vec2(1.0, 1.0);
const vec2 UNITS = vec2(1.5, 1.5);

bool onCurve(float f, float thickness) {
    float g = length(vec2(dFdx(f), dFdy(f)));
    float d = abs(f);
    return d <= g * thickness;
}

float unit(float v) {
    float sv = 0.5 * (v - 0.5);
    float f = fract(sv);
    return abs(2.0 * f - 1.0) - 0.5;
}

vec3 colorAt(vec2 xy) {
    vec2 p = xy * UNITS * UNIT; 
    bool unitX = onCurve(unit(xy.x * UNITS.x), 1.0);
    bool unitY = onCurve(unit(xy.y * UNITS.y), 1.0);
    bool axisX = onCurve(p.x, 2.0);
    bool axisY = onCurve(p.y, 2.0);
    bool onSin = onCurve(p.y - sin(p.x), 3.0);
    bool onF = onCurve(p.y - p.x * (p.x * p.x - 1.0), 3.0);

    return onF            ? vec3(0.0, 0.0, 1.0)
         : onSin          ? vec3(1.0, 0.0, 00)
         : axisX || axisY ? vec3(0.0) 
         : unitX || unitY ? vec3(0.5)
         : vec3(1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float halfPixelSize = 1.0 / min(iResolution.x, iResolution.y);
    vec2 xy = (2.0 * fragCoord - iResolution.xy) * halfPixelSize;

    fragColor = vec4(sqrt(0.25 * (
        colorAt(xy + vec2(0.0, 0.0)) +
        colorAt(xy + vec2(halfPixelSize, 0.0)) +
        colorAt(xy + vec2(0.0, halfPixelSize)) +
        colorAt(xy + vec2(halfPixelSize))
    )), 1.0);
}
